import { h } from "preact"

const css = `
.okf-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  align-items: center;
  margin-bottom: 1rem;
  font-size: 0.8rem;
}
.okf-meta .okf-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.1rem 0.5rem;
  border-radius: 999px;
  background: var(--lightgray);
  color: var(--darkgray);
  white-space: nowrap;
}
.okf-meta .okf-badge.status-verified { background: #dde8fb; color: #1f4e91; }
.okf-meta .okf-badge.status-human-reviewed { background: #d9f2e3; color: #1c6b3f; font-weight: 600; }
.okf-meta .okf-badge.status-draft { background: #fbeedd; color: #8a5a20; }
.okf-meta .okf-badge.status-stable { background: #d9f2e3; color: #1c6b3f; }
.okf-meta .okf-badge.status-deprecated { background: #ececec; color: #6b6b6b; text-decoration: line-through; }
.okf-meta .okf-badge.status-stale { background: #fbdcdc; color: #922b2b; }
.okf-sources {
  margin: 0 0 1.5rem 0;
  font-size: 0.85rem;
}
.okf-sources ul {
  margin: 0.25rem 0 0 0;
  padding-left: 1.2rem;
}
.okf-sources li {
  margin: 0.15rem 0;
}
.okf-sources .okf-source-meta {
  color: var(--gray);
  font-size: 0.85em;
}
`

// Trim a full ISO-8601 timestamp down to its date portion for compact display.
// Leaves plain dates (and anything that isn't a recognizable timestamp) untouched.
function formatDate(value) {
  if (value === undefined || value === null || value === "") return ""
  if (value instanceof Date) return value.toISOString().slice(0, 10)
  const s = String(value)
  const tIndex = s.indexOf("T")
  return tIndex === -1 ? s : s.slice(0, tIndex)
}

// stale_after is due once its date is strictly before today (UTC, date-only
// comparison so the badge doesn't flip at an arbitrary time of day).
function isPastDue(staleAfter) {
  if (!staleAfter) return false
  const d = staleAfter instanceof Date ? staleAfter : new Date(String(staleAfter))
  if (Number.isNaN(d.getTime())) return false
  const now = new Date()
  const todayUTC = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate())
  const dueUTC = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate())
  return dueUTC < todayUTC
}

function Badge(label, value, extraClass) {
  if (value === undefined || value === null || value === "") return null
  return h(
    "span",
    { class: `okf-badge ${extraClass ?? ""}` },
    h("strong", null, label + ": "),
    String(value),
  )
}

// One badge per `verified` entry, rendered as "by (at)". Entries whose actor
// follows the `human:<id>` convention (see authoring guide, OKF §7) get the
// stronger "human-reviewed" style so a human sign-off reads differently from
// an agent or process attestation.
function verifiedBadges(verified) {
  if (!Array.isArray(verified) || verified.length === 0) return []
  return verified
    .map((entry, i) => {
      if (!entry || typeof entry !== "object" || !entry.by) return null
      const isHuman = String(entry.by).startsWith("human:")
      const at = formatDate(entry.at)
      const label = at ? `${entry.by} (${at})` : String(entry.by)
      return h(
        "span",
        {
          key: `okf-verified-${i}`,
          class: `okf-badge status-verified${isHuman ? " status-human-reviewed" : ""}`,
        },
        isHuman ? h("strong", null, "✓ ") : null,
        label,
      )
    })
    .filter(Boolean)
}

const OkfMetaConstructor = (_userOpts) => {
const OkfMeta = (props) => {
  const fm = props?.fileData?.frontmatter ?? {}
  const status = fm.status
  const type = fm.type
  const generated = fm.generated ?? {}
  const verified = fm.verified
  const staleAfter = fm.stale_after
  const sources = fm.sources
  const stale = isPastDue(staleAfter)

  const hasAnyMeta =
    status ||
    type ||
    generated.by ||
    generated.at ||
    (Array.isArray(verified) && verified.length) ||
    stale ||
    (sources && sources.length)

  if (!hasAnyMeta) return null

  const badges = [
    Badge("type", type),
    Badge("status", status, status ? `status-${status}` : ""),
    stale ? Badge("stale after", formatDate(staleAfter), "status-stale") : null,
    ...verifiedBadges(verified),
    generated.by ? Badge("generated by", generated.by) : null,
    generated.at ? Badge("generated at", formatDate(generated.at)) : null,
  ].filter(Boolean)

  const sourcesList =
    Array.isArray(sources) && sources.length
      ? h(
          "div",
          { class: "okf-sources" },
          h("strong", null, "Sources"),
          h(
            "ul",
            null,
            sources.map((s) => {
              const metaParts = []
              if (s.author) metaParts.push(s.author)
              if (s.last_modified) metaParts.push(`updated ${formatDate(s.last_modified)}`)
              return h(
                "li",
                { key: s.id ?? s.resource },
                h(
                  "a",
                  { href: s.resource, target: "_blank", rel: "noopener noreferrer" },
                  s.title ?? s.resource,
                ),
                metaParts.length ? h("span", { class: "okf-source-meta" }, ` — ${metaParts.join(", ")}`) : null,
              )
            }),
          ),
        )
      : null

  return h(
    "div",
    { class: "okf-meta-block" },
    badges.length ? h("div", { class: "okf-meta" }, ...badges) : null,
    sourcesList,
  )
}

OkfMeta.css = css
return OkfMeta
}

export { OkfMetaConstructor as OkfMeta }
